type Command =
  | { kind: "move"; steps: number }
  | { kind: "turn"; direction: "left" | "right" }
  | { kind: "say"; text: string };

const FACINGS: string[] = ["north", "east", "south", "west"];
const STEPS: [number, number][] = [[0, 1], [1, 0], [0, -1], [-1, 0]];   // one [dx, dy] per facing, same order

function run(commands: Command[]): { x: number; y: number; facing: string; log: string[] } {
  let x = 0, y = 0, dir = 0;
  const log: string[] = [];
  for (const c of commands) {
    switch (c.kind) {
      case "move": {
        const [dx, dy] = STEPS[dir];
        x += dx * c.steps;
        y += dy * c.steps;
        break;
      }
      case "turn":
        dir = (dir + (c.direction === "right" ? 1 : 3)) % 4;
        break;
      case "say":
        log.push(`(${x}, ${y}): ${c.text}`);
        break;
      default: {
        const unreachable: never = c;
        throw new Error(`unknown command ${JSON.stringify(unreachable)}`);
      }
    }
  }
  return { x, y, facing: FACINGS[dir], log };
}

function isCommand(x: unknown): x is Command {
  if (typeof x !== "object" || x === null) return false;
  const c = x as Record<string, unknown>;
  switch (c.kind) {
    case "move": return typeof c.steps === "number";
    case "turn": return c.direction === "left" || c.direction === "right";
    case "say": return typeof c.text === "string";
    default: return false;
  }
}

function parseProgram(json: string): Command[] {
  const data: unknown = JSON.parse(json);
  if (!Array.isArray(data)) throw new Error("a program must be an array");
  return data.filter(isCommand);
}

unitTests:
test("moving and turning", () => {
  const r = run([
    { kind: "move", steps: 2 },
    { kind: "turn", direction: "right" },
    { kind: "move", steps: 3 },
    { kind: "say", text: "hello" },
    { kind: "turn", direction: "left" },
    { kind: "turn", direction: "left" },
    { kind: "turn", direction: "left" },
    { kind: "move", steps: 1 },
  ]);
  checkEq(r, { x: 3, y: 1, facing: "south", log: ["(3, 2): hello"] });
});

test("turning all the way round", () => {
  const right = { kind: "turn", direction: "right" } as const;
  checkEq(run([right, right, right, right]).facing, "north");
  checkEq(run([{ kind: "turn", direction: "left" }]).facing, "west");
  checkEq(run([]), { x: 0, y: 0, facing: "north", log: [] });
});

test("type guard", () => {
  check(isCommand({ kind: "move", steps: 1 }), "a move");
  check(isCommand({ kind: "say", text: "" }), "a say");
  check(!isCommand({ kind: "move", steps: "1" }), "steps must be a number");
  check(!isCommand({ kind: "turn", direction: "up" }), "direction must be left or right");
  check(!isCommand({ kind: "fly" }), "unknown kind");
  check(!isCommand(null) && !isCommand("move") && !isCommand(undefined), "not objects");
});

test("parsing a program", () => {
  const program = parseProgram('[{"kind": "move", "steps": 4}, {"kind": "jump"}, {"kind": "say", "text": "done"}, 7]');
  checkEq(program.length, 2);
  checkEq(run(program).log, ["(0, 4): done"]);
  checkThrows(() => parseProgram('{"kind": "move"}'));
});

